/**
 * ArkTS touch forward into the winit fork's event pump (p4 G8: the NDK
 * XComponent touch callback is structurally unreachable in the node-mode
 * layout). Parallel arrays, one entry per touch point; xs/ys are
 * displayX/displayY in vp (every TouchObject flavor is vp) — the native side
 * multiplies by the display scale captured at entry to reach the pump's px
 * contract; eventType is the ArkTS TouchType value (0 Down, 1 Up, 2 Move,
 * 3 Cancel).
 */
export declare function notifyTouchEvent(eventType: number, ids: Array<number>, xs: Array<number>, ys: Array<number>, forces: Array<number>, deviceId: number): void

